package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_evaluation_assignment") public class EvaluationAssignment extends RspAuditedEntity{
 public enum Role{EXAMINER,VALIDATOR,PANEL_MEMBER,REFERENCE_CHECKER,SECRETARIAT,OBSERVER,ALTERNATE}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="stage_id",length=36)private String stageId;@Column(name="candidate_id",length=36)private String candidateId;@Column(name="employee_no",nullable=false,length=100)private String employeeNo;@Enumerated(EnumType.STRING)@Column(name="assignment_role",nullable=false,length=30)private Role role;@Column(nullable=false)private boolean active;@Column(name="current_assignment_key",length=300)private String currentAssignmentKey;@Column(name="alternate_for_employee_no",length=100)private String alternateForEmployeeNo;@Column(name="assigned_by",nullable=false,length=100)private String assignedBy;@Column(name="assigned_at",nullable=false)private Instant assignedAt;@Column(name="deactivated_by",length=100)private String deactivatedBy;@Column(name="deactivated_at")private Instant deactivatedAt;@Column(name="deactivation_reason",length=1000)private String deactivationReason;
 protected EvaluationAssignment(){}public EvaluationAssignment(String agency,String proceeding,String stage,String candidate,String employee,Role role,String alternate,String actor,Instant at){super(agency);proceedingId=requiredText(proceeding,"proceedingId");stageId=optionalText(stage);candidateId=optionalText(candidate);employeeNo=requiredText(employee,"employeeNo");this.role=Objects.requireNonNull(role);alternateForEmployeeNo=optionalText(alternate);if(role==Role.ALTERNATE&&alternateForEmployeeNo==null)throw new IllegalArgumentException("An alternate requires the employee being replaced");assignedBy=requiredText(actor,"actor");assignedAt=Objects.requireNonNull(at);currentAssignmentKey=proceedingId+":"+Objects.requireNonNullElse(stageId,"*")+":"+Objects.requireNonNullElse(candidateId,"*")+":"+employeeNo.toUpperCase(Locale.ROOT)+":"+role;active=true;}
 public void deactivate(String actor,String reason,Instant at){if(active){deactivatedBy=requiredText(actor,"actor");deactivationReason=requiredText(reason,"reason");deactivatedAt=Objects.requireNonNull(at);currentAssignmentKey=null;active=false;}}
 public String getProceedingId(){return proceedingId;}public String getStageId(){return stageId;}public String getCandidateId(){return candidateId;}public String getEmployeeNo(){return employeeNo;}public Role getRole(){return role;}public boolean isActive(){return active;}public String getAlternateForEmployeeNo(){return alternateForEmployeeNo;}
}
